using System.Text.Json.Nodes;
namespace RisingLands;
public static class OpponentV75Tests {
 static int checks;
 static void Check(bool ok,string label){checks++;if(!ok)throw new Exception("FAIL v75: "+label);Console.WriteLine("PASS v75: "+label);}
 public static Simulation Load(string root){var w=LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/MONDE04.ETA"));new VisualCatalog().Apply(w);return new(w);}
 static void Step(Simulation s,int ticks){for(int i=0;i<ticks;i++)s.Step();}
 static Simulation EndingFixture(string root){var w=Load(root).World;var settler=w.Units.First(a=>a.Owner==0&&a.Type==9&&a.LegacyState==14);foreach(var ids in w.BuildingResidents.Values)ids.Remove(settler.Slot);w.Buildings.Add(new(900,16,0,40+40*256));w.BuildingResidents[900]=new(){settler.Slot};return new(w);}
 public static void Run(string root){
  var s=Load(root);Check(s.OpponentEnabled,"mission four enables Red Clan");Check(s.World.Units.Count(a=>a.Owner==1)==29&&s.World.Buildings.Count(b=>b.Owner==1)==4,"native red initial population and buildings");int playerFood=s.World.Resources[0],playerRock=s.World.Resources[4];Step(s,300);Check(s.World.Units.Any(a=>a.Owner==1&&(a.FoodJob>0||a.MineJob>0)),"red workers receive collection jobs");Check(s.Recruitments.Any(j=>j.Owner==1),"red barracks trains using its own residents and stocks");Check(s.World.Resources[0]<=playerFood&&s.World.Resources[4]==playerRock,"enemy activity does not debit player stocks");
  var copy=Load(root);copy.Restore(s.Serialize());Check(s.Serialize()==copy.Serialize(),"AI and active jobs restore exactly");Step(s,1200);Step(copy,1200);Check(s.Serialize()==copy.Serialize(),"AI continues deterministically after load");copy=Load(root);copy.Restore(s.Serialize());Check(copy.Serialize()==s.Serialize(),"harvest and recruitment ledgers reload");
  Check(s.Recruitments.Any(j=>j.Owner==1&&j.Finished),"trained red troop exits native barracks");
  Check(s.Opponent.Deposited[1]>0||s.Cultures.Any(c=>s.World.Buildings.Any(b=>b.Slot==c.Building&&b.Owner==1)&&c.Food+c.Consumed>0),"red food is physically harvested and delivered");
  var arena=Load(root);var defender=arena.World.Units.First(a=>a.Owner==1&&a.Type==8&&VisualCatalog.Visible(a));var invader=arena.World.Units.First(a=>a.Owner==0&&a.Type==0&&VisualCatalog.Visible(a));invader.X=defender.X+1024;invader.Y=defender.Y;int hp=invader.Health;Step(arena,60);Check(invader.Health<hp,"red clan detects and fights a visible invader without player order");
  var friendly=Load(root);defender=friendly.World.Units.First(a=>a.Owner==1&&a.Type==8&&VisualCatalog.Visible(a));invader=friendly.World.Units.First(a=>a.Owner==0&&a.Type==0&&VisualCatalog.Visible(a));invader.X=defender.X+1024;invader.Y=defender.Y;friendly.Campaign.Alliances[1]=true;hp=invader.Health;Step(friendly,90);Check(invader.Health==hp&&defender.AttackTarget<0,"alliance prevents automatic hostilities");
  var fog=Load(root);Step(fog,30);Check(fog.World.Units.Where(a=>a.Owner==1).All(a=>a.AttackTarget<0)&&fog.Opponent.TargetsSeen.Count==0,"enemy cannot target unseen player across map");
  var siege=Load(root);foreach(var a in siege.World.Units.Where(a=>a.Owner==1&&VisualCatalog.Visible(a)))a.Health=0;var building=siege.World.Buildings.First(b=>b.Owner==1&&b.Type==3);var fighter=siege.World.Units.First(a=>a.Owner==0&&a.Type==1);int cell=Enumerable.Range(0,65536).Where(c=>Math.Abs((c&255)-(building.Cell&255))+Math.Abs((c>>8)-(building.Cell>>8))<8&&siege.Passable(c&255,c>>8)).OrderBy(c=>Math.Abs((c&255)-(building.Cell&255))+Math.Abs((c>>8)-(building.Cell>>8))).First();fighter.X=(cell&255)*1024;fighter.Y=(cell>>8)*1024;
  Check(siege.AttackBuilding(fighter,building.Slot),"player can order attack on enemy warehouse");Step(siege,60);copy=Load(root);copy.Restore(siege.Serialize());Check(copy.Serialize()==siege.Serialize(),"siege windup and building damage survive load");for(int i=0;i<1000&&!siege.DestroyedBuilding(building.Slot);i++)siege.Step();Check(siege.DestroyedBuilding(building.Slot)&&!siege.World.Buildings.Any(b=>b.Slot==building.Slot),"native warehouse damage limit destroys structure");copy=Load(root);copy.Restore(siege.Serialize());Check(copy.Serialize()==siege.Serialize()&&copy.DestroyedAt(building.Cell),"destroyed structure never returns after load");
  var peace=Load(root);var sanctuary=peace.World.Buildings.First(b=>b.Owner==1&&b.Type==2);var messenger=peace.World.Units.First(a=>a.Owner==0&&a.Type==0);messenger.Type=10;Check(peace.SendMessenger(messenger,sanctuary.Slot),"messenger can travel to native Red Clan sanctuary");Check(!peace.CanAttack(peace.World.Units.First(a=>a.Owner==1&&a.Type==0&&VisualCatalog.Visible(a)),messenger),"messenger protected from enemy attacks");
  var bad=JsonNode.Parse(s.Serialize())!;bad["Resources"]![5]=bad["Resources"]![5]!.GetValue<int>()+1;try{copy.Restore(bad.ToJsonString());throw new Exception("forged stock accepted");}catch(InvalidDataException){Check(true,"forged enemy resources rejected");}
  // A long physical simulation exercises crop births, hunger, production and jobs.
  Step(s,9000);copy=Load(root);copy.Restore(s.Serialize());Check(s.Serialize()==copy.Serialize(),"long mission state remains loadable");
  var ending=EndingFixture(root);ending.Campaign.Alliances[1]=true;Step(ending,99);Check(!ending.MissionWon&&ending.MissionChecks==99,"market and alliance are evaluated for consecutive ticks");ending.Step();Check(ending.MissionWon,"mission four alliance path completes");ending.RequestNextMission();Check(ending.ChooseNextResearch(0)&&ending.ProgressForNextMission().CompletedMission==4,"mission four opens research choice for mission five");var endedCopy=EndingFixture(root);endedCopy.Restore(ending.Serialize());Check(endedCopy.Serialize()==ending.Serialize()&&endedCopy.MissionWon,"mission four completed state and transition survive load");
  var construction=Load(root);var builder=construction.World.Units.First(a=>a.Owner==1&&a.Type==7&&a.Slot==9);int food=construction.World.Resources[0],rock=construction.World.Resources[4];bool started=false;foreach(int c in Enumerable.Range(0,65536).Where(c=>(c&255)<construction.World.Width&&(c>>8)<construction.World.Height).OrderBy(c=>Math.Abs((c&255)-builder.X/1024)+Math.Abs((c>>8)-builder.Y/1024)))if(construction.StartConstruction(builder,3,c)){started=true;break;}Check(started&&construction.Constructions.Last().Owner==1&&construction.World.Resources[0]==food&&construction.World.Resources[4]==rock,"enemy construction charges only native Red Clan resources");for(int i=0;i<10000&&!construction.Complete(construction.Constructions.Last());i++)construction.Step();Check(construction.Complete(construction.Constructions.Last())&&construction.World.Buildings.Any(b=>b.Slot==construction.Constructions.Last().Id&&b.Owner==1),"enemy builder finishes its own warehouse");copy=Load(root);copy.Restore(construction.Serialize());Check(copy.Serialize()==construction.Serialize(),"enemy building ownership and construction survive save/load");
  SaveSlotTests.Run(root);
  Console.WriteLine("ALL v75 TESTS PASSED: "+checks);
 }
}
